const listRunLinks = `-- name: ListRunLinks :many
SELECT run_id, spec_doc_id, version_id FROM run_link WHERE run_id = ?1 ORDER BY spec_doc_id
`

func (q *Queries) ListRunLinks(ctx context.Context, runID uuid.UUID) ([]RunLink, error) {
	rows, err := q.db.QueryContext(ctx, listRunLinks, runID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RunLink
	for rows.Next() {
		var i RunLink
		if err := rows.Scan(&i.RunID, &i.SpecDocID, &i.VersionID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const putCache = `-- name: PutCache :exec
INSERT INTO cache_entry (key_hash, result, created_at) VALUES (?1, ?2, ?3)
ON CONFLICT (key_hash) DO NOTHING
`

type PutCacheParams struct {
	KeyHash   string
	Result    dbtype.JSON
	CreatedAt time.Time
}

func (q *Queries) PutCache(ctx context.Context, arg PutCacheParams) error {
	_, err := q.db.ExecContext(ctx, putCache, arg.KeyHash, arg.Result, arg.CreatedAt)
	return err
}

const runningRunFor = `-- name: RunningRunFor :one
SELECT id, workspace_id, spec_doc_id, version_id, profile_key, profile_version, kind, status, stage, roles, prompt_versions, tokens_in, tokens_out, cost_estimate, cache_hits, error, started_at, finished_at, notes, stages, decisions_hash FROM review_run
WHERE spec_doc_id = ?1 AND kind = 'full' AND status IN ('queued', 'running')
ORDER BY started_at DESC
LIMIT 1
`

func (q *Queries) RunningRunFor(ctx context.Context, specDocID uuid.UUID) (ReviewRun, error) {
	row := q.db.QueryRowContext(ctx, runningRunFor, specDocID)
	var i ReviewRun
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.SpecDocID,
		&i.VersionID,
		&i.ProfileKey,
		&i.ProfileVersion,
		&i.Kind,
		&i.Status,
		&i.Stage,
		&i.Roles,
		&i.PromptVersions,
		&i.TokensIn,
		&i.TokensOut,
		&i.CostEstimate,
		&i.CacheHits,
		&i.Error,
		&i.StartedAt,
		&i.FinishedAt,
		&i.Notes,
		&i.Stages,
		&i.DecisionsHash,
	)
	return i, err
}

