const updateMCPConnection = `-- name: UpdateMCPConnection :exec
UPDATE mcp_connection
SET name = ?1, transport = ?2, command_or_url = ?3,
    secret_encrypted = ?4, secret_last4 = ?5,
    tool_allowlist = ?6, is_search = ?7, search_tool = ?8,
    hosts = ?9, fetch_tool = ?10
WHERE workspace_id = ?11 AND id = ?12
`

type UpdateMCPConnectionParams struct {
	Name            string
	Transport       string
	CommandOrUrl    dbtype.JSON
	SecretEncrypted []byte
	SecretLast4     string
	ToolAllowlist   dbtype.JSON
	IsSearch        bool
	SearchTool      string
	Hosts           dbtype.JSON
	FetchTool       string
	WorkspaceID     uuid.UUID
	ID              uuid.UUID
}

func (q *Queries) UpdateMCPConnection(ctx context.Context, arg UpdateMCPConnectionParams) error {
	_, err := q.db.ExecContext(ctx, updateMCPConnection,
		arg.Name,
		arg.Transport,
		arg.CommandOrUrl,
		arg.SecretEncrypted,
		arg.SecretLast4,
		arg.ToolAllowlist,
		arg.IsSearch,
		arg.SearchTool,
		arg.Hosts,
		arg.FetchTool,
		arg.WorkspaceID,
		arg.ID,
	)
	return err
}

